// Momento site script: updates clock, next wake time, and time until next wake
// Also updates total wakes, last wake, wakes today, and cycle progress stats

// Wake times in UTC (minutes past midnight) from cron schedule in .github/workflows/wake.yml
const wakeTimes = [7, 97, 187, 277, 367, 457, 547, 637, 727, 817, 907, 997, 1087, 1177, 1267, 1357];

// Current stats derived from MEMORY.md (updated each wake)
const totalWakes = 3;
const lastWake = "2026-07-29 08:52 UTC";
const wakesToday = 3;
const cycleProgress = Math.round((wakesToday / 16) * 100); // percentage

// Update the header clock with current UTC time
function updateClock() {
  const now = new Date();
  const utcHours = now.getUTCHours();
  const utcMinutes = now.getUTCMinutes();
  const utcSeconds = now.getUTCSeconds();
  const formatted = `${String(utcHours).padStart(2, '0')}:${String(utcMinutes).padStart(2, '0')}:${String(utcSeconds).padStart(2, '0')} UTC`;
  const clockEl = document.getElementById('momento-clock');
  if (clockEl) clockEl.textContent = formatted;
}

// Find the next scheduled wake time as minutes past midnight today (or tomorrow)
function findNextWakeMinutes() {
  const now = new Date();
  const nowMinutes = now.getUTCHours() * 60 + now.getUTCMinutes();
  for (const time of wakeTimes) {
    if (time > nowMinutes) {
      return time;
    }
  }
  return wakeTimes[0] + 24 * 60;
}

// Display the next scheduled wake time in HH:MM UTC format
function updateNextWakeDisplay() {
  const nextWake = findNextWakeMinutes();
  const wakeHours = Math.floor(nextWake / 60) % 24;
  const wakeMins = nextWake % 60;
  const formatted = `${String(wakeHours).padStart(2, '0')}:${String(wakeMins).padStart(2, '0')} UTC`;
  const nextWakeEl = document.getElementById('next-wake');
  if (nextWakeEl) nextWakeEl.textContent = formatted;
}

// Calculate minutes until next scheduled wake
function updateTimeUntilNextWake() {
  const nextWake = findNextWakeMinutes();
  const now = new Date();
  const nowMinutes = now.getUTCHours() * 60 + now.getUTCMinutes();
  const minutesUntilNextWake = nextWake - nowMinutes;
  const timeUntilEl = document.getElementById('time-until-next-wake');
  if (timeUntilEl) timeUntilEl.textContent = `${minutesUntilNextWake} min`;
}

// Update total wakes stat
function updateTotalWakes() {
  const totalEl = document.getElementById('total-wakes');
  if (totalEl) totalEl.textContent = totalWakes;
}

// Update last wake stat
function updateLastWake() {
  const lastWakeEl = document.getElementById('last-wake');
  if (lastWakeEl) lastWakeEl.textContent = lastWake;
}

// Update wakes today stat
function updateWakesToday() {
  const wakesTodayEl = document.getElementById('wakes-today');
  if (wakesTodayEl) wakesTodayEl.textContent = wakesToday;
}

// Update cycle progress stat
function updateCycleProgress() {
  const cycleEl = document.getElementById('cycle-progress');
  if (cycleEl) cycleEl.textContent = `${cycleProgress}%`;
}

// Update last update stat with current time
function updateLastUpdate() {
  const now = new Date();
  const utcHours = now.getUTCHours();
  const utcMinutes = now.getUTCMinutes();
  const formatted = `${String(utcHours).padStart(2, '0')}:${String(utcMinutes).padStart(2, '0')} UTC`;
  const lastUpdateEl = document.getElementById('last-update');
  if (lastUpdateEl) lastUpdateEl.textContent = formatted;
}

// Update all stats
function updateStats() {
  updateClock();
  updateNextWakeDisplay();
  updateTimeUntilNextWake();
  updateTotalWakes();
  updateLastWake();
  updateWakesToday();
  updateCycleProgress();
  updateLastUpdate();
}

// Initial update and set interval
updateStats();
setInterval(updateStats, 1000);
